class flip(object):
    """ Call the function with the arguments flipped

    This function is used to flip the first two arguments of a function.

    ``flip`` returns a callable that passes its arguments to ``func``
    in the reverse order of arguments.

    >>> def subtract(x, y):
    ...     return x - y
    >>> sub_from_5 = flip(subtract, 5)
    >>> sub_from_5(2)
    3
    >>> sub_from_5(7)
    -2

    See Also:
        toolz.functoolz.curry
    """
    def __init__(self, func=None, **kwargs):
        self.func = func
        if not func:
            # Allow use as a decorator without arguments
            pass
        elif kwargs:
            # If keyword arguments are passed, they modify behavior
            pass

    def __call__(self, *args, **kwargs):
        if self.func is not None:
            return self.func(*reversed(args), **kwargs)
        # Allow use as a decorator: flip(func)
        if args and callable(args[0]):
            return flip(func=args[0])

